/** @typedef {import('./index.js').PermsModule} PermsModule */
/** @typedef {Promise<Record<string, unknown>>} PermResult */
/**
 * Grants a permission to another user.
 * @this {PermsModule}
 * @param {string} username
 * @param {string} permission
 * @returns {PermResult}
 */
export function grantUser(this: import("./index.js").PermsModule, username: string, permission: string): PermResult;
/**
 * Grants a permission to a group.
 * @this {PermsModule}
 * @param {string} groupUid
 * @param {string} permission
 * @returns {PermResult}
 */
export function grantGroup(this: import("./index.js").PermsModule, groupUid: string, permission: string): PermResult;
/**
 * Grants a permission to an app.
 * @this {PermsModule}
 * @param {string} appUid
 * @param {string} permission
 * @returns {PermResult}
 */
export function grantApp(this: import("./index.js").PermsModule, appUid: string, permission: string): PermResult;
/**
 * Grants a permission to an app for any user (developer grant).
 * @this {PermsModule}
 * @param {string} appUid
 * @param {string} permission
 * @returns {PermResult}
 */
export function grantAppAnyUser(this: import("./index.js").PermsModule, appUid: string, permission: string): PermResult;
/**
 * Grants a permission to an origin.
 * @this {PermsModule}
 * @param {string} origin
 * @param {string} permission
 * @returns {PermResult}
 */
export function grantOrigin(this: import("./index.js").PermsModule, origin: string, permission: string): PermResult;
/**
 * Revokes a permission from another user.
 * @this {PermsModule}
 * @param {string} username
 * @param {string} permission
 * @returns {PermResult}
 */
export function revokeUser(this: import("./index.js").PermsModule, username: string, permission: string): PermResult;
/**
 * Revokes a permission from a group.
 * @this {PermsModule}
 * @param {string} groupUid
 * @param {string} permission
 * @returns {PermResult}
 */
export function revokeGroup(this: import("./index.js").PermsModule, groupUid: string, permission: string): PermResult;
/**
 * Revokes a permission from an app.
 * @this {PermsModule}
 * @param {string} appUid
 * @param {string} permission
 * @returns {PermResult}
 */
export function revokeApp(this: import("./index.js").PermsModule, appUid: string, permission: string): PermResult;
/**
 * Revokes an app's any-user (developer) permission.
 * @this {PermsModule}
 * @param {string} appUid
 * @param {string} permission
 * @returns {PermResult}
 */
export function revokeAppAnyUser(this: import("./index.js").PermsModule, appUid: string, permission: string): PermResult;
/**
 * Revokes a permission from an origin.
 * @this {PermsModule}
 * @param {string} origin
 * @param {string} permission
 * @returns {PermResult}
 */
export function revokeOrigin(this: import("./index.js").PermsModule, origin: string, permission: string): PermResult;
export type PermsModule = import("./index.js").PermsModule;
export type PermResult = Promise<Record<string, unknown>>;
